package main

import (
	"bytes"
	"compress/zlib"
	"encoding/base64"
	"fmt"
	"os"
)

func enc(data []byte, flush bool) string {
	var b bytes.Buffer
	w := zlib.NewWriter(&b)
	w.Write(data)
	if flush {
		w.Flush()
	}
	w.Close()
	return base64.URLEncoding.EncodeToString(b.Bytes())
}

func main() {
	data, _ := os.ReadFile("/tmp/gztest/in.json")
	fmt.Println("noflush:", enc(data, false))
	fmt.Println("flush:  ", enc(data, true))
}
EOF
